import { showButtonFeedback } from "/components/messages/action-buttons/simple-action-buttons.js";
import { open as openSurface } from "/js/surfaces.js";

const DESKTOP_FORMATS = ["odt", "ods", "odp", "docx", "xlsx", "pptx"];

function basename(path = "") {
  const value = String(path || "").split("?")[0].split("#")[0];
  return value.split("/").filter(Boolean).pop() || "document";
}

function extensionFromPath(path = "") {
  const name = basename(path);
  const index = name.lastIndexOf(".");
  return index > 0 ? name.slice(index + 1).toLowerCase() : "";
}

function parseMaybeJson(value) {
  if (!value) return null;
  if (typeof value === "object") return value;
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  if (!trimmed.startsWith("{")) return null;
  try {
    const parsed = JSON.parse(trimmed);
    return parsed && typeof parsed === "object" ? parsed : null;
  } catch {
    return null;
  }
}

function truthy(value) {
  if (value === true) return true;
  if (value === false || value == null) return false;
  if (typeof value === "number") return value !== 0;
  return ["1", "true", "yes", "y", "on"].includes(String(value).trim().toLowerCase());
}

function firstValue(...values) {
  for (const value of values) {
    if (value != null && String(value).trim() !== "") return value;
  }
  return "";
}

export function parseDocumentResult(content) {
  return parseMaybeJson(content) || {};
}

export function normalizeDocumentMetadata(args = {}, result = {}) {
  const kvps = parseMaybeJson(args?.kvps) || args?.kvps || {};
  const document = result?.document && typeof result.document === "object"
    ? result.document
    : {};
  const path = String(firstValue(
    result.path,
    kvps.path,
    args.path,
    document.path,
  ));
  const title = String(firstValue(
    result.title,
    kvps.title,
    kvps.basename,
    args.title,
    document.basename,
    basename(path),
  ));
  const format = String(firstValue(
    result.format,
    result.extension,
    kvps.format,
    kvps.extension,
    args.format,
    document.extension,
    extensionFromPath(path),
  )).toLowerCase().replace(/^\./, "");

  return {
    action: String(firstValue(result.action, kvps.action, args.action)).toLowerCase(),
    file_id: String(firstValue(result.file_id, kvps.file_id, args.file_id, document.file_id)),
    path,
    title,
    format,
    extension: format,
    size: firstValue(result.size, kvps.size, document.size),
    version: firstValue(result.version, kvps.version, args.version, document.version),
    last_modified: firstValue(result.last_modified, kvps.last_modified, args.last_modified, document.last_modified),
    exists: firstValue(result.exists, kvps.exists, document.exists),
    open_in_canvas: truthy(firstValue(result.open_in_canvas, kvps.open_in_canvas, args.open_in_canvas)),
    open_in_desktop: truthy(firstValue(result.open_in_desktop, kvps.open_in_desktop, args.open_in_desktop)),
  };
}

export function documentFromLog(args = {}, result = {}) {
  return normalizeDocumentMetadata(args, result);
}

export async function openDocumentInDesktop(document = {}) {
  await openSurface("office", {
    path: document.path || "",
    file_id: document.file_id || "",
    refresh: true,
    source: "message-action",
  });
}

export async function openOfficeArtifact(document = {}) {
  if (document.format === 'pdf' || document.extension === 'pdf') return downloadDocument(document);
  await openDocumentInDesktop(document);
}

function usesDesktop(doc = {}) {
  const format = String(doc.format || doc.extension || "").toLowerCase();
  return DESKTOP_FORMATS.includes(format);
}

function canvasActionTitle(doc = {}) {
  const format = String(doc.format || doc.extension || "").toLowerCase();
  if (format === 'pdf') return 'Download PDF';
  if (["odt", "docx"].includes(format)) return "Open in canvas with Writer";
  if (["ods", "xlsx"].includes(format)) return "Open in canvas with Calc";
  if (["odp", "pptx"].includes(format)) return "Open in canvas with Impress";
  return "Open in canvas";
}

function documentIcon(doc = {}) {
  const format = String(doc.format || doc.extension || "").toLowerCase();
  if (["ods", "xlsx"].includes(format)) return "table_chart";
  if (["odp", "pptx"].includes(format)) return "slideshow";
  return usesDesktop(doc) ? "description" : "draft";
}

function statusLine(doc = {}) {
  const parts = [];
  if (doc.path) parts.push(doc.path);
  if (doc.version) parts.push(`v${doc.version}`);
  return parts.join(" | ");
}

export function buildDocumentFileCard(document = {}) {
  const card = globalThis.document.createElement("span");
  card.className = "document-file-card";
  card.setAttribute("role", "button");
  card.setAttribute("tabindex", "0");
  card.setAttribute("aria-label", canvasActionTitle(document));
  card.setAttribute("title", canvasActionTitle(document));

  const icon = globalThis.document.createElement("x-icon");
  icon.className = "document-file-card-icon";
  icon.name = documentIcon(document);
  card.appendChild(icon);

  const meta = globalThis.document.createElement("span");
  meta.className = "document-file-card-meta";

  const name = globalThis.document.createElement("span");
  name.className = "document-file-card-name";
  name.textContent = document.title || basename(document.path);
  meta.appendChild(name);

  const detail = globalThis.document.createElement("span");
  detail.className = "document-file-card-path";
  detail.textContent = statusLine(document) || "Office artifact";
  meta.appendChild(detail);
  card.appendChild(meta);

  if (document.format) {
    const badge = globalThis.document.createElement("span");
    badge.className = "document-file-card-badge";
    badge.textContent = String(document.format).toUpperCase();
    card.appendChild(badge);
  }

  if (document.path || document.file_id) {
    card.addEventListener("click", () => openOfficeArtifact(document));
    card.addEventListener("keydown", (event) => {
      if (event.key !== "Enter" && event.key !== " ") return;
      event.preventDefault();
      void openOfficeArtifact(document);
    });
  } else {
    card.setAttribute("aria-disabled", "true");
    card.removeAttribute("tabindex");
  }

  return card;
}

export function downloadDocument(doc = {}) {
  const path = String(doc.path || "");
  if (!path) return;
  const link = globalThis.document.createElement("a");
  link.href = `/api/download_work_dir_file?path=${encodeURIComponent(path)}`;
  link.download = String(doc.title || basename(path));
  globalThis.document.body.appendChild(link);
  link.click();
  globalThis.document.body.removeChild(link);
}

export function createDocumentActionButton(icon, label, handler = null, options = {}) {
  const button = globalThis.document.createElement("button");
  button.type = "button";
  button.className = ["action-button", "document-file-action", options.className]
    .filter(Boolean)
    .join(" ");
  button.setAttribute("aria-label", options.ariaLabel || options.title || label);
  button.setAttribute("title", options.title || label);

  if (icon) {
    const iconEl = globalThis.document.createElement("x-icon");
    iconEl.name = icon;
    button.appendChild(iconEl);
  }

  if (typeof handler === "function") {
    button.addEventListener("click", async (event) => {
      event.stopPropagation();
      const iconEl = button.querySelector("x-icon");
      const originalIcon = iconEl?.name || "";
      try {
        await handler();
        if (originalIcon) showButtonFeedback(button, true, originalIcon);
      } catch (err) {
        console.error("Document action failed:", err);
        if (originalIcon) showButtonFeedback(button, false, originalIcon);
      }
    });
  }

  return button;
}

export function buildDocumentFileActionButtons(document = {}) {
  const hasTarget = Boolean(document?.path || document?.file_id);
  const buttons = [];
  if (hasTarget && usesDesktop(document)) {
    buttons.push(
      createDocumentActionButton(
        "open_in_new",
        "Open in canvas",
        () => openOfficeArtifact(document),
        {
          className: "document-file-action-primary",
          title: canvasActionTitle(document),
          ariaLabel: canvasActionTitle(document),
        },
      ),
    );
  }
  if (document?.path) {
    buttons.push(
      createDocumentActionButton("download", "Download", () => downloadDocument(document)),
    );
  }
  return buttons;
}

import asyncio
import uuid
from pathlib import Path
from helpers.api import ApiHandler, Request
from helpers import plugins
from usr.plugins.office.helpers import document_store, libreoffice
from usr.plugins.office.helpers.runtime import get_runtime

FORMATS = {'odt','ods','odp','docx','xlsx','pptx'}

class OfficeSession(ApiHandler):
    async def process(self, input: dict, request: Request) -> dict:
        if plugins.get_toggle_state('office') != 'enabled':
            return {'ok':False,'error':'Office is disabled'}
        if input.get('action') == 'status':
            return {'ok':True, **get_runtime().status()}
        try:
            return await asyncio.to_thread(dispatch, input)
        except Exception as exc:
            return {'ok':False,'error':str(exc)}


def dispatch(input):
    action = str(input.get('action') or 'open')
    runtime = get_runtime()
    context_id = str(input.get('context_id') or input.get('ctxid') or '')
    if action == 'sync':
        return {'ok':True, **(runtime.sync(save=False) if runtime.ready else runtime.status())}
    if action == 'stop':
        runtime.stop()
        return {'ok':True, **runtime.status()}
    if action == 'resize':
        return runtime.call('resize',width=input.get('width'),height=input.get('height'))
    if action == 'browse':
        path = document_store.normalize_path(input.get('path') or document_store.default_open_path(context_id),context_id=context_id)
        entries=[]
        for child in sorted(path.iterdir() if path.exists() else [],key=lambda item:(not item.is_dir(),item.name.lower())):
            if child.name == '.office-drafts':
                continue
            if child.is_dir() or child.suffix.lower().lstrip('.') in FORMATS:
                entries.append({'name':child.name,'path':str(child),'directory':child.is_dir()})
        try:
            parent=document_store.normalize_path(path.parent,context_id=context_id)
        except PermissionError:
            parent=path
        return {'ok':True,'path':str(path),'parent':str(parent),'entries':entries}
    if action == 'home':
        return {'ok':True,'path':document_store.default_open_path(context_id)}
    with runtime.lock:
        if action == 'create':
            fmt = str(input.get('format') or 'odt')
            if fmt not in FORMATS:
                raise ValueError('Unsupported Office format')
            path = input.get('path','')
            if input.get('draft'):
                path = str(document_store.document_home(context_id) / '.office-drafts' / uuid.uuid4().hex / ('Untitled.' + fmt))
            doc = document_store.create_document(kind=input.get('kind','document'),title='' if input.get('draft') else input.get('title') or 'Untitled',
                fmt=fmt, content=input.get('content',''),path=path,context_id=context_id)
        else:
            doc = document_store.get_document(input['file_id']) if input.get('file_id') else document_store.register_document(input.get('path',''), context_id=context_id)
        if doc['extension'] not in FORMATS:
            raise ValueError('Text documents use the Editor surface')
        identifier = doc['file_id']
        if action in {'create','open'}:
            result = runtime.open(doc,mode=input.get('mode','edit'))
            return {**result, 'documents':runtime.status()['documents']}
        if action == 'close':
            runtime.close(identifier,save=input.get('save',True))
            return {'ok':True, **runtime.status()}
        if action == 'versions':
            return {'ok':True,'versions':document_store.version_history(identifier)}
        synced = runtime.sync(identifier)
        identifier = synced.get('document', {}).get('file_id', identifier)
        doc = document_store.get_document(identifier)
        if action == 'save':
            return {'ok':True,'document':doc}
        if action == 'rename':
            target = document_store.normalize_path(input['target_path'],context_id=context_id)
            was_open = identifier in runtime.opened
            if was_open:
                runtime.close(identifier)
            updated = document_store.rename_document(identifier,target,context_id=context_id)
            if was_open:
                return runtime.open(updated)
            return {'ok':True,'document':updated}
        if action == 'save_as':
            target = document_store.normalize_path(input['target_path'],context_id=context_id)
            if target.suffix.lstrip('.') != doc['extension']:
                raise ValueError('Save As keeps the format; use Export to convert')
            if target.exists():
                raise FileExistsError(str(target))
            if doc.get('draft'):
                runtime.close(identifier)
                updated = document_store.rename_document(identifier,target,context_id=context_id)
            else:
                document_store._write_atomic(target,Path(doc['path']).read_bytes(),source=Path(doc['path']))
                updated = document_store.register_document(target,context_id=context_id)
            result = runtime.open(updated)
            if not doc.get('draft'):
                runtime.close(identifier)
            return {**result, 'documents':runtime.status()['documents']}
        if action == 'export':
            return libreoffice.convert_document(doc['path'],input.get('target_format','pdf'))
        if action == 'restore':
            was_open = identifier in runtime.opened
            if was_open:
                runtime.close(identifier)
            restored = document_store.restore_version(identifier,int(input['version_id']))
            if was_open:
                return runtime.open(restored)
            return {'ok':True,'document':restored}
    raise ValueError('Unsupported Office action')

from __future__ import annotations

import zipfile
from pathlib import Path
from typing import Any


ODF_MIMETYPES = {
    "odt": "application/vnd.oasis.opendocument.text",
    "ods": "application/vnd.oasis.opendocument.spreadsheet",
    "odp": "application/vnd.oasis.opendocument.presentation",
}


def collect_status():
    from usr.plugins.office.helpers.runtime import get_runtime
    return {'ok':True, **get_runtime().status()}


def validate_docx(path: str | Path) -> dict[str, Any]:
    source = Path(path)
    if not source.exists():
        return {"ok": False, "error": f"File not found: {source}"}
    try:
        with zipfile.ZipFile(source) as archive:
            archive.getinfo("[Content_Types].xml")
            archive.getinfo("word/document.xml")
    except Exception as exc:
        return {"ok": False, "error": f"DOCX package validation failed: {exc}"}

    return {'ok': True}


def validate_odf(path: str | Path) -> dict[str, Any]:
    source = Path(path)
    if not source.exists():
        return {"ok": False, "error": f"File not found: {source}"}
    ext = source.suffix.lower().lstrip(".")
    expected_mimetype = ODF_MIMETYPES.get(ext)
    if not expected_mimetype:
        return {"ok": False, "error": f"Unsupported ODF extension: {ext}"}
    try:
        with zipfile.ZipFile(source) as archive:
            first = archive.infolist()[0]
            mimetype = archive.read("mimetype").decode("utf-8")
            archive.getinfo("content.xml")
            archive.getinfo("META-INF/manifest.xml")
    except Exception as exc:
        return {"ok": False, "error": f"ODF package validation failed: {exc}"}
    if first.filename != "mimetype" or first.compress_type != zipfile.ZIP_STORED:
        return {"ok": False, "error": "ODF mimetype must be the first uncompressed package entry."}
    if mimetype != expected_mimetype:
        return {"ok": False, "error": f"ODF mimetype mismatch: expected {expected_mimetype}, got {mimetype}"}
    return {"ok": True}


def convert_document(path, target_format, output_dir=None):
    import base64
    from usr.plugins.office.helpers import document_store
    from usr.plugins.office.helpers.runtime import get_runtime
    source = Path(path)
    target_format = str(target_format).lower().lstrip('.')
    if target_format not in {'odt','ods','odp','docx','xlsx','pptx','pdf'}:
        raise ValueError('Unsupported export format')
    target = (Path(output_dir) if output_dir else source.parent) / (source.stem + '.' + target_format)
    target = document_store.normalize_path(target)
    if target.exists():
        raise FileExistsError(f'Export target already exists: {target}')
    doc = document_store.register_document(source)
    runtime = get_runtime()
    with runtime.lock:
        doc = runtime.sync(doc['file_id']).get('document', doc)
        result = runtime.call('export', **runtime.payload(doc), target_format=target_format)
        document_store._write_atomic(target, base64.b64decode(result['data'],validate=True), source=source)
    return {'ok':True, 'path':str(target)}

import RFB from '/plugins/_browser/webui/vendor/novnc/core/rfb.js';
const screen = document.getElementById('screen');
const status = document.getElementById('status');
let rfb, timer, stopped = false;
const viewer = window.a0OfficeViewer = {connected:false, paste(text) {
  if (!rfb || !viewer.connected) return;
  rfb.clipboardPasteFrom(text);
  rfb.sendKey(0xffe3,'ControlLeft',true);
  rfb.sendKey(0x76,'KeyV');
  rfb.sendKey(0xffe3,'ControlLeft',false);
}};
async function connect() {
  if (stopped) return;
  try {
    const response = await fetch('./credentials',{credentials:'same-origin',cache:'no-store'});
    if (!response.ok) throw new Error('Office session is unavailable');
    const credentials = await response.json();
    const url = new URL('./ws', location.href);
    url.protocol = location.protocol === 'https:' ? 'wss:' : 'ws:';
    const client = rfb = new RFB(screen,url.href,{credentials});
    viewer.rfb = client;
    client.scaleViewport = true;
    client.resizeSession = false;
    client.addEventListener('connect',()=>{viewer.connected=true;status.hidden=true;client.focus();});
    client.addEventListener('disconnect',()=>{
      viewer.connected=false;status.hidden=false;status.textContent='Office disconnected. Reconnecting…';
      if (!stopped) timer=setTimeout(connect,1500);
    });
    client.addEventListener('clipboard',({detail})=>{
      if (document.hasFocus()) void navigator.clipboard?.writeText(detail.text).catch(()=>{});
    });
  } catch (error) {
    status.hidden=false;status.textContent=error.message;
    if (!stopped) timer=setTimeout(connect,1500);
  }
}
document.addEventListener('keydown',async event=>{
  if (!viewer.connected || !(event.ctrlKey||event.metaKey)) return;
  if(event.key.toLowerCase()==='s'){event.preventDefault();event.stopImmediatePropagation();parent.postMessage({officeAction:event.shiftKey?'save_as':'save'},location.origin);return;}
  if(event.key.toLowerCase()!=='v')return;
  event.preventDefault();event.stopImmediatePropagation();
  try {viewer.paste(await navigator.clipboard.readText());}
  catch {status.hidden=false;status.textContent='Allow clipboard access to paste into Office';}
},true);
window.addEventListener('pagehide',()=>{stopped=true;clearTimeout(timer);rfb?.disconnect();});
void connect();

"""Register Office tokens on A0's existing authenticated VNC transport."""
from pathlib import Path
from urllib.parse import urlsplit
from starlette.responses import FileResponse, JSONResponse, PlainTextResponse
from starlette.websockets import WebSocket
from helpers import plugins, virtual_desktop
from plugins._browser.helpers.viewer_gateway import BrowserVncGateway

ASSETS = Path(__file__).resolve().parents[1] / 'webui'

class OfficeVncGateway(BrowserVncGateway):
    async def __call__(self, scope, receive, send):
        if scope['type'] == 'websocket':
            endpoint, path = self.endpoint(scope)
            if path != '/ws':
                await WebSocket(scope,receive=receive,send=send).close(code=1008)
                return
            await self.websocket(scope,receive,send)
        elif scope['type'] == 'http':
            await self.http(scope,receive,send)

    def allowed(self, scope):
        if plugins.get_toggle_state('office') != 'enabled' or not self.is_authorized(scope):
            return False
        headers = dict(scope.get('headers', []))
        if headers.get(b'sec-fetch-site', b'').lower() in {b'cross-site', b'same-site'}:
            return False
        origin = headers.get(b'origin', b'').decode('latin-1')
        if origin:
            try:
                parsed = urlsplit(origin)
            except ValueError:
                return False
            if parsed.scheme not in {'http', 'https'} or parsed.netloc.lower() != headers.get(b'host', b'').decode('latin-1').lower():
                return False
        elif scope['type'] == 'websocket':
            return False
        return True

    def endpoint(self, scope):
        route = self.session_request(self.relative_path(scope))
        if not route:
            return None, ''
        endpoint = virtual_desktop.proxy_for_token(route[0])
        if not endpoint or endpoint.owner != 'office-vnc' or endpoint.host != '127.0.0.1':
            return None, ''
        return endpoint, route[1]

    async def http(self, scope, receive, send):
        if not self.allowed(scope):
            await PlainTextResponse('Access denied',status_code=403)(scope,receive,send)
            return
        endpoint, path = self.endpoint(scope)
        headers = {'Cache-Control':'no-store','X-Frame-Options':'SAMEORIGIN','X-Content-Type-Options':'nosniff'}
        if not endpoint or scope.get('method') not in {'GET','HEAD'}:
            response = PlainTextResponse('Office viewer not found',status_code=404)
        elif path == '/credentials':
            response = JSONResponse({'password':[REDACTED]},headers=headers)
        elif path in {'/index.html','/vnc.js'}:
            response = FileResponse(ASSETS / ('vnc.html' if path == '/index.html' else 'vnc.js'),headers=headers)
        else:
            response = PlainTextResponse('Not found',status_code=404)
        await response(scope,receive,send)


def register():
    # A0 v3 has a fixed VNC mount; dispatch only our tokens, including after a Hub install.
    if getattr(BrowserVncGateway, '_office_router', None):
        return
    original = BrowserVncGateway.__call__
    async def route(self, scope, receive, send):
        path = self.relative_path(scope)
        if path.startswith('/session/office-'):
            await OfficeVncGateway(self.flask_app)(scope,receive,send)
        else:
            await original(self,scope,receive,send)
    BrowserVncGateway._office_router = route
    BrowserVncGateway._office_original = original
    BrowserVncGateway.__call__ = route


def unregister():
    router = getattr(BrowserVncGateway, '_office_router', None)
    if router and BrowserVncGateway.__call__ is router:
        BrowserVncGateway.__call__ = BrowserVncGateway._office_original
        del BrowserVncGateway._office_router
        del BrowserVncGateway._office_original

"""Private LibreOffice display using the same minimal Xvnc runtime as Tuxee."""
from __future__ import annotations

import configparser
import os
from pathlib import Path
import secrets
import select
import shutil
import socket
import struct
import subprocess
import threading
import time
import uuid

import native_display

DEFAULT_WIDTH, DEFAULT_HEIGHT = 1024, 768
_keyboard = {}


def keyboard_options():
    return _keyboard


def collect_status():
    binaries = {name: shutil.which(name) or '' for name in ('tuxee-Xvnc', 'tuxee-vncpasswd', 'xrandr')}
    missing = [name for name, path in binaries.items() if not path]
    return {'available': not missing, 'missing': missing, 'binaries': binaries}


class OfficeDisplay:
    def __init__(self, context_id):
        self.context_id = str(context_id)
        self.token = 'office-' + uuid.uuid4().hex
        self.state_dir = Path('/run/a0-office') / self.token
        self.display = None
        self.port = 0
        self.password = ''
        self.width, self.height = DEFAULT_WIDTH, DEFAULT_HEIGHT
        self._server = None
        self._lock = threading.RLock()

    @property
    def display_name(self):
        return f':{self.display}' if self.display is not None else ''

    @property
    def xauthority(self):
        return str(self.state_dir / 'Xauthority')

    @property
    def gtk_config(self):
        return str(self.state_dir / 'gtk')

    def _fit_file_dialog(self):
        # Without a window manager, GTK's default picker can exceed the display.
        path = Path(self.gtk_config) / 'glib-2.0/settings/keyfile'
        path.parent.mkdir(parents=True, exist_ok=True)
        settings = configparser.ConfigParser(interpolation=None)
        settings.read(path)
        section = 'org/gtk/settings/file-chooser'
        if not settings.has_section(section):
            settings.add_section(section)
        settings[section].update({'window-size': f'({self.width}, {self.height})', 'window-position': '(0, 0)'})
        temporary = path.with_suffix('.tmp')
        with temporary.open('w') as stream:
            settings.write(stream)
        temporary.replace(path)

    def _env(self):
        return {**os.environ, 'DISPLAY': self.display_name, 'XAUTHORITY': self.xauthority, 'XKB_CONFIG_ROOT': '/opt/tuxee-gui/xkb'}

    def _write_xauthority(self, cookie, number=''):
        fields = (b'', str(number).encode(), b'MIT-MAGIC-COOKIE-1', cookie)
        payload = struct.pack('>H', 65535) + b''.join(struct.pack('>H', len(v)) + v for v in fields)
        with open(self.xauthority, 'wb') as stream:
            os.chmod(self.xauthority, 0o600)
            stream.write(payload)

    def ensure_display(self):
        with self._lock:
            if self._running(self._server) and self.display is not None:
                return self.display_name
            self._stop_locked()
            status = collect_status()
            if not status['available']:
                raise RuntimeError('Office display needs: ' + ', '.join(status['missing']))
            self.state_dir.mkdir(parents=True, exist_ok=True, mode=0o700)
            self.state_dir.chmod(0o700)
            self._fit_file_dialog()
            self.password = [REDACTED]
            passwd = [REDACTED] / 'passwd'
            with passwd.open('wb') as stream:
                passwd.chmod(0o600)
                subprocess.run(['tuxee-vncpasswd', '-f'], input=(self.password + '\n').encode(),
                               stdout=stream, stderr=subprocess.PIPE, check=True, timeout=5)
            cookie = secrets.token_bytes(16)
            self._write_xauthority(cookie)
            self.port = self._free_port()
            read_fd, write_fd = os.pipe()
            try:
                with (self.state_dir / 'display.log').open('ab') as log:
                    self._server = subprocess.Popen([
                        'tuxee-Xvnc', '-displayfd', str(write_fd), '-geometry', f'{self.width}x{self.height}',
                        '-depth', '24', '-rfbport', str(self.port), '-interface', '127.0.0.1',
                        '-localhost', '-SecurityTypes', 'VncAuth', '-PasswordFile', str(passwd),
                        '-AlwaysShared', '-DisconnectClients=0', '-SendPrimary=0', '-SetPrimary=0',
                        '-auth', self.xauthority, '-nolisten', 'tcp', '-extension', 'MIT-SHM',
                        '-fp', 'built-ins', '-xkbdir', '/opt/tuxee-gui/xkb', '-s', '0', '-noreset',
                    ], stdin=subprocess.DEVNULL, stdout=log, stderr=log, pass_fds=(write_fd,), env={**os.environ, 'XKB_BINDIR': '/opt/tuxee-gui/bin'})
            except BaseException:
                os.close(read_fd)
                self._stop_locked()
                raise
            finally:
                os.close(write_fd)
            try:
                readable, _, _ = select.select([read_fd], [], [], 10)
                number = os.read(read_fd, 32).decode().strip() if readable else ''
                if not number.isdigit() or not self._running(self._server):
                    raise RuntimeError('Xvnc did not become ready; see sandbox display.log')
                self.display = int(number)
                self._write_xauthority(cookie, number)
                deadline = time.monotonic() + 5
                while time.monotonic() < deadline:
                    if native_display.current_display_size(self.display, env=self._env()):
                        break
                    time.sleep(.05)
                else:
                    raise RuntimeError('Office X display did not accept its private credentials')
                self._apply_keyboard_layout()
                return self.display_name
            except BaseException:
                self._stop_locked()
                raise
            finally:
                os.close(read_fd)

    def ensure_viewer(self, width=0, height=0):
        with self._lock:
            self.ensure_display()
            self.resize(width or self.width, height or self.height)
            return {'available': True, 'port': self.port, 'password': [REDACTED],
                    'width': self.width, 'height': self.height}

    def resize(self, width, height):
        with self._lock:
            width, height = native_display.normalize_size(width, height)
            if self.display is None or not self._running(self._server):
                self.width, self.height = width, height
                return {'ok': False, 'error': 'Office display is unavailable.',
                        'width': self.width, 'height': self.height}
            # A0 owns this private display; repeated viewer requests need no X client.
            if (width, height) == (self.width, self.height):
                return {'ok': True, 'width': width, 'height': height, 'resized': False}
            result = native_display.resize_display(display=self.display, width=width, height=height,
                                                   settle_seconds=0, env=self._env())
            if result.get('ok'):
                self.width, self.height = width, height
                self._fit_file_dialog()
            return result

    def _apply_keyboard_layout(self):
        options = keyboard_options()
        if self.display is None or not options.get('layout'):
            return
        command = [shutil.which('setxkbmap') or 'setxkbmap', '-display', self.display_name, '-layout', options['layout'], '-I/opt/tuxee-gui/xkb']
        if options.get('variant'):
            command.extend(['-variant', options['variant']])
        subprocess.run(command, env=self._env(), check=True, capture_output=True, timeout=5)

    def close(self):
        with self._lock:
            self._stop_locked()
            shutil.rmtree(self.state_dir, ignore_errors=True)

    def _stop_locked(self):
        if self._running(self._server):
            self._server.terminate()
            try:
                self._server.wait(timeout=2)
            except subprocess.TimeoutExpired:
                self._server.kill()
                self._server.wait(timeout=2)
        self._server = None
        self.display = None
        self.port = 0
        self.password = ''

    @staticmethod
    def _running(process):
        return process is not None and process.poll() is None

    @staticmethod
    def _free_port():
        with socket.socket() as probe:
            probe.bind(('127.0.0.1', 0))
            return probe.getsockname()[1]

